/* Regression test for what a caller must RENDER when
 * _gx_canvas_drawing_initiate() returns GX_DRAW_NESTING_EXCEEDED.
 *
 * guix_canvas_draw_nesting_overflow_no_output covers the other half of the
 * contract: that the overflow is detected and that the draw context stack is
 * left untouched.  It says nothing about the pixels, and issue #148's fix
 * originally answered "draw nothing", which silently dropped text that GUIX had
 * always drawn.
 *
 * A widget such as a multi line text view pushes a nested context on itself for
 * one reason only: to narrow the clipping rectangle to its client area.  When
 * the stack is full there is nothing to push, but the caller's context is still
 * the correct context to draw through - it belongs to the same widget - so the
 * widget narrows that context's clipping rectangle, draws, and restores it.
 *
 * Tests:
 *   1. The text is still drawn when the draw context stack is full.
 *   2. The borrowed context is restored: nesting count, context pointer and
 *      clipping rectangle are all exactly as they were.
 *   3. The pixels produced at maximum nesting depth are identical to the pixels
 *      produced when a nested context is available.
 */

#include <stdio.h>
#include <string.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_system.h"
#include "gx_widget.h"
#include "gx_multi_line_text_view.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_canvas_draw_nesting_overflow_render_no_output",
    0, 0, 0, 0
};

int main(int argc, char **argv)
{
    tx_kernel_enter();
    return 0;
}

static VOID control_thread_entry(ULONG input);

VOID tx_application_define(void *first_unused_memory)
{
    gx_validation_control_thread_create(control_thread_entry);
    gx_validation_application_define(first_unused_memory);
    gx_validation_watchdog_create(100);
}

#ifdef WIN32
#undef WIN32
#endif

#include "gx_validation_wrapper.h"
#include "demo_guix_all_widgets.c"

/* Sum every byte of the canvas frame buffer.  Working in bytes keeps the
   comparison independent of the colour depth, so the test behaves the same in
   every build configuration.  */
static ULONG canvas_checksum(GX_CANVAS *canvas)
{
ULONG     sum = 0;
ULONG     index;
GX_UBYTE *memory = (GX_UBYTE *)canvas -> gx_canvas_memory;

    for (index = 0; index < canvas -> gx_canvas_memory_size; index++)
    {
        sum += memory[index];
    }

    return sum;
}

static VOID control_thread_entry(ULONG input)
{
int                      failed_tests = 0;
GX_CANVAS               *canvas;
GX_MULTI_LINE_TEXT_VIEW *text_view;
GX_RECTANGLE             size;
GX_RECTANGLE             saved_dirty;
GX_DRAW_CONTEXT         *saved_context;
GX_UBYTE                 saved_nesting;
UINT                     status;
UINT                     index;
ULONG                    blank_sum;
ULONG                    overflow_sum;
ULONG                    nested_sum;

    canvas = root -> gx_window_root_canvas;
    text_view = &text_screen.text_screen_text_view_1;

    /* Bring up the screen that owns the multi line text view, so that the widget
       has a clip rectangle and a view list of its own.  */
    ToggleScreen((GX_WINDOW *)&text_screen, (GX_WINDOW *)&button_screen);
    tx_thread_sleep(10);

    /* Give the widget a non-zero whitespace.  The rectangle it passes to
       _gx_canvas_drawing_initiate() is its client area shrunk by the whitespace,
       so the narrowed clipping rectangle becomes strictly smaller than the
       widget's own clip rectangle.  That is what makes the narrowing matter.  */
    gx_multi_line_text_view_whitespace_set(text_view, 6);
    tx_thread_sleep(10);

    size = text_view -> gx_widget_size;

    /* Pre-condition: the draw context stack must be clean.  */
    EXPECT_EQ(0, (int)canvas -> gx_canvas_draw_nesting);
    EXPECT_EQ(GX_NULL, _gx_system_current_draw_context);

    /* Fill the draw context stack, drawing on the text view itself so that every
       context carries the widget's view list.  The last one is the context the
       widget has to borrow.  */
    for (index = 0; index < GX_MAX_CONTEXT_NESTING; index++)
    {
        status = gx_canvas_drawing_initiate(canvas, (GX_WIDGET *)text_view, &size);
        EXPECT_EQ(GX_SUCCESS, status);
    }

    saved_nesting = canvas -> gx_canvas_draw_nesting;
    saved_context = _gx_system_current_draw_context;
    saved_dirty = saved_context -> gx_draw_context_dirty;

    memset(canvas -> gx_canvas_memory, 0, canvas -> gx_canvas_memory_size);
    blank_sum = canvas_checksum(canvas);

    /* Test 1: the text is drawn even though the stack is full.  */
    _gx_multi_line_text_view_text_draw(text_view,
                                       text_view -> gx_multi_line_text_view_normal_text_color);

    overflow_sum = canvas_checksum(canvas);

    if (overflow_sum == blank_sum)
    {
        PRINT_ERROR("no pixels were written at maximum draw context nesting depth");
        failed_tests++;
    }

    /* Test 2: the borrowed context is handed back untouched.  */
    EXPECT_EQ(saved_nesting, canvas -> gx_canvas_draw_nesting);
    EXPECT_EQ(saved_context, _gx_system_current_draw_context);
    EXPECT_EQ(saved_dirty.gx_rectangle_left, saved_context -> gx_draw_context_dirty.gx_rectangle_left);
    EXPECT_EQ(saved_dirty.gx_rectangle_top, saved_context -> gx_draw_context_dirty.gx_rectangle_top);
    EXPECT_EQ(saved_dirty.gx_rectangle_right, saved_context -> gx_draw_context_dirty.gx_rectangle_right);
    EXPECT_EQ(saved_dirty.gx_rectangle_bottom, saved_context -> gx_draw_context_dirty.gx_rectangle_bottom);

    /* Unwind the stack.  */
    for (index = 0; index < GX_MAX_CONTEXT_NESTING; index++)
    {
        gx_canvas_drawing_complete(canvas, GX_FALSE);
    }

    EXPECT_EQ(0, (int)canvas -> gx_canvas_draw_nesting);
    EXPECT_EQ(GX_NULL, _gx_system_current_draw_context);

    /* Test 3: draw the same text again with room left on the stack, so that the
       nested context is really pushed, and compare the two renderings.  */
    status = gx_canvas_drawing_initiate(canvas, (GX_WIDGET *)text_view, &size);
    EXPECT_EQ(GX_SUCCESS, status);

    memset(canvas -> gx_canvas_memory, 0, canvas -> gx_canvas_memory_size);

    _gx_multi_line_text_view_text_draw(text_view,
                                       text_view -> gx_multi_line_text_view_normal_text_color);

    nested_sum = canvas_checksum(canvas);

    gx_canvas_drawing_complete(canvas, GX_FALSE);

    EXPECT_EQ(0, (int)canvas -> gx_canvas_draw_nesting);
    EXPECT_EQ(GX_NULL, _gx_system_current_draw_context);

    EXPECT_EQ(nested_sum, overflow_sum);

    if (failed_tests == 0)
    {
        gx_validation_print_test_result(TEST_SUCCESS);
        exit(0);
    }
    else
    {
        gx_validation_print_test_result(TEST_FAIL);
        exit(1);
    }
}
